def kakao_map_me(api_key, **_extra):
    import json, os, datetime, time, re, base64, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0446000" if __import__("os").path.isdir("./environment_mix/0446000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _gen_id(prefix):
        t = int(time.time() * 1000)
        r = random.getrandbits(40)
        raw = f"{prefix}:{t}:{r}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = token.replace("O", "8").replace("I", "9").replace("L", "7")
        return f"{prefix}_{token[:26]}"

    t0 = time.time()

    if not (isinstance(api_key, str) and re.match(r"^kmap_key_[0-9A-HJKMNP-TV-Z]{18,}$", api_key)):
        usage = _load("usage_events.json")
        now = _now()
        usage.append({
            "id": _gen_id("uevt"),
            "api_key_id": None,
            "recommendation_run_id": None,
            "event_type": "request_received",
            "units": 0,
            "http_status": 400,
            "upstream_status": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "metadata": {"route": "kakao_map_me", "error": "INVALID_API_KEY_FORMAT"},
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "api_key does not match required format.", field="api_key")

    api_keys = _load("api_keys.json")
    usage = _load("usage_events.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key:
            key_row = k
            break

    now = _now()
    # always log the call
    usage.append({
        "id": _gen_id("uevt"),
        "api_key_id": api_key if key_row else None,
        "recommendation_run_id": None,
        "event_type": "request_received",
        "units": 0,
        "http_status": None,
        "upstream_status": None,
        "latency_ms": None,
        "metadata": {"route": "kakao_map_me"},
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })

    if key_row is None:
        # mark failed
        fin = _now()
        usage.append({
            "id": _gen_id("uevt"),
            "api_key_id": None,
            "recommendation_run_id": None,
            "event_type": "request_failed",
            "units": 0,
            "http_status": 401,
            "upstream_status": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "metadata": {"route": "kakao_map_me", "error": "UNKNOWN_API_KEY"},
            "created_at": _iso(fin),
            "updated_at": _iso(fin),
        })
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is invalid.")

    if key_row.get("status") != "active":
        fin = _now()
        usage.append({
            "id": _gen_id("uevt"),
            "api_key_id": key_row.get("id"),
            "recommendation_run_id": None,
            "event_type": "request_failed",
            "units": 0,
            "http_status": 401,
            "upstream_status": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "metadata": {"route": "kakao_map_me", "error": f"KEY_{key_row.get('status', 'inactive').upper()}"},
            "created_at": _iso(fin),
            "updated_at": _iso(fin),
        })
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is not active.")

    # update last_used_at
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    # compute consumption
    minute_limit = key_row.get("quota_requests_per_minute", 0)
    day_limit = key_row.get("quota_requests_per_day", 0)
    if not isinstance(minute_limit, int) or minute_limit < 0:
        minute_limit = 0
    if not isinstance(day_limit, int) or day_limit < 0:
        day_limit = 0

    minute_start = now - datetime.timedelta(minutes=1)
    day_start = now - datetime.timedelta(days=1)

    def _sum_units(since_dt):
        total = 0
        for e in usage:
            if e.get("api_key_id") != key_row["id"]:
                continue
            ts = _parse_iso(e.get("created_at"))
            if ts is None or ts < since_dt:
                continue
            u = e.get("units")
            if isinstance(u, int) and not isinstance(u, bool) and u >= 0:
                total += u
        return total

    per_minute_used = _sum_units(minute_start)
    per_day_used = _sum_units(day_start)

    fin = _now()
    usage.append({
        "id": _gen_id("uevt"),
        "api_key_id": key_row["id"],
        "recommendation_run_id": None,
        "event_type": "request_succeeded",
        "units": 0,
        "http_status": 200,
        "upstream_status": None,
        "latency_ms": int((time.time() - t0) * 1000),
        "metadata": {"route": "kakao_map_me"},
        "created_at": _iso(fin),
        "updated_at": _iso(fin),
    })

    _save("api_keys.json", api_keys)
    _save("usage_events.json", usage)

    return {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "owner_type": key_row.get("owner_type"),
            "owner_id": key_row.get("owner_id"),
            "status": key_row.get("status"),
            "quota_requests_per_minute": minute_limit,
            "quota_requests_per_day": day_limit,
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "scopes": ["places:recommend", "runs:read"],
        "quota": {
            "per_minute": {"used": per_minute_used, "limit": minute_limit},
            "per_day": {"used": per_day_used, "limit": day_limit},
        },
    }

def kakao_map_recommendation_runs_list(api_key, status=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0446000" if __import__("os").path.isdir("./environment_mix/0446000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _gen_id(prefix):
        t = int(time.time() * 1000)
        r = random.getrandbits(40)
        raw = f"{prefix}:{t}:{r}".encode("utf-8")
        token = base64.b32encode(hashlib.sha256(raw).digest()).decode("ascii").rstrip("=")
        token = token.replace("O", "8").replace("I", "9").replace("L", "7")
        return f"{prefix}_{token[:26]}"

    def _b64url_encode(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64url_decode(tok):
        if not isinstance(tok, str) or not tok:
            return None
        pad = "=" * ((4 - len(tok) % 4) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    t0 = time.time()

    if not (isinstance(api_key, str) and re.match(r"^kmap_key_[0-9A-HJKMNP-TV-Z]{18,}$", api_key)):
        usage = _load("usage_events.json")
        now = _now()
        usage.append({
            "id": _gen_id("uevt"),
            "api_key_id": None,
            "recommendation_run_id": None,
            "event_type": "request_received",
            "units": 0,
            "http_status": 400,
            "upstream_status": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "metadata": {"route": "kakao_map_recommendation_runs_list", "error": "INVALID_API_KEY_FORMAT"},
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("usage_events.json", usage)
        return _err("VALIDATION_ERROR", "api_key does not match required format.", field="api_key")

    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

    ca = _parse_iso(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time.", field="created_after")

    cb = _parse_iso(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time.", field="created_before")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.", field="page_size")

    api_keys = _load("api_keys.json")
    runs = _load("recommendation_runs.json")
    usage = _load("usage_events.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key:
            key_row = k
            break

    now = _now()
    usage.append({
        "id": _gen_id("uevt"),
        "api_key_id": api_key if key_row else None,
        "recommendation_run_id": None,
        "event_type": "request_received",
        "units": 0,
        "http_status": None,
        "upstream_status": None,
        "latency_ms": None,
        "metadata": {"route": "kakao_map_recommendation_runs_list"},
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })

    if key_row is None or key_row.get("status") != "active":
        fin = _now()
        usage.append({
            "id": _gen_id("uevt"),
            "api_key_id": api_key if key_row else None,
            "recommendation_run_id": None,
            "event_type": "request_failed",
            "units": 0,
            "http_status": 401,
            "upstream_status": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "metadata": {"route": "kakao_map_recommendation_runs_list", "error": "UNAUTHORIZED"},
            "created_at": _iso(fin),
            "updated_at": _iso(fin),
        })
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is invalid or not active.")

    # pagination token: {"cursor_created_at": "...", "cursor_id": "..."}
    cursor = None
    if page_token is not None:
        cursor = _b64url_decode(page_token)
        if not isinstance(cursor, dict) or "cursor_created_at" not in cursor or "cursor_id" not in cursor:
            return _err("VALIDATION_ERROR", "Invalid page_token.", field="page_token")
        if _parse_iso(cursor.get("cursor_created_at")) is None or not isinstance(cursor.get("cursor_id"), str):
            return _err("VALIDATION_ERROR", "Invalid page_token.", field="page_token")

    # scope: visible to the api_key_id (owner scoping could be by owner_id, but schema provides api_key_id on run)
    visible = [r for r in runs if r.get("api_key_id") == key_row["id"]]

    # filters
    if status is not None:
        visible = [r for r in visible if r.get("status") == status]

    if ca is not None:
        visible = [r for r in visible if (_parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) >= ca]
    if cb is not None:
        visible = [r for r in visible if (_parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) < cb]

    # sort newest first: created_at desc, tie id desc
    def _key(r):
        dt = _parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")
    visible.sort(key=_key, reverse=True)

    if cursor is not None:
        cdt = _parse_iso(cursor["cursor_created_at"])
        cid = cursor["cursor_id"]
        def _after_cursor(r):
            rdt = _parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            rid = r.get("id") or ""
            # since list is desc, continue after items "less than" cursor tuple
            return (rdt, rid) < (cdt, cid)
        visible = [r for r in visible if _after_cursor(r)]

    total = len(visible)
    page = visible[:page_size]
    has_more = total > page_size

    next_token = None
    if has_more and page:
        last = page[-1]
        next_token = _b64url_encode({
            "cursor_created_at": last.get("created_at"),
            "cursor_id": last.get("id"),
        })

    fin = _now()
    usage.append({
        "id": _gen_id("uevt"),
        "api_key_id": key_row["id"],
        "recommendation_run_id": None,
        "event_type": "request_succeeded",
        "units": 0,
        "http_status": 200,
        "upstream_status": None,
        "latency_ms": int((time.time() - t0) * 1000),
        "metadata": {"route": "kakao_map_recommendation_runs_list", "returned": len(page)},
        "created_at": _iso(fin),
        "updated_at": _iso(fin),
    })

    _save("usage_events.json", usage)

    return {
        "data": page,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
        },
    }

def kakao_map_recommendation_items_list(api_key, recommendation_run_id, page_size=None, page_token=None, **_extra):
    import json, os, datetime, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0446000" if __import__("os").path.isdir("./environment_mix/0446000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_usage(event_type, api_key_id=None, recommendation_run_id=None, units=0, http_status=None, upstream_status=None, latency_ms=None, metadata=None):
        usage = _load("usage_events.json")
        ts = datetime.datetime.now(datetime.timezone.utc)
        rid = "kmap_use_" + ts.strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "recommendation_run_id": recommendation_run_id,
            "event_type": event_type,
            "units": int(units),
            "http_status": http_status,
            "upstream_status": upstream_status,
            "latency_ms": latency_ms,
            "metadata": metadata if isinstance(metadata, dict) else {},
            "created_at": ts.isoformat(),
            "updated_at": ts.isoformat(),
        }
        usage.append(row)
        _save("usage_events.json", usage)
        return row

    def _decode_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or tok == "":
            return None
        try:
            pad = "=" * (-len(tok) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_token(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(api_key, str):
        _append_usage("request_failed", api_key_id=None, recommendation_run_id=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "VALIDATION_ERROR", "field": "api_key"})
        return _err("VALIDATION_ERROR", "api_key must be a string", field="api_key")
    if not api_key.startswith("kmap_key_"):
        _append_usage("request_failed", api_key_id=None, recommendation_run_id=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "VALIDATION_ERROR", "field": "api_key"})
        return _err("VALIDATION_ERROR", "api_key format is invalid", field="api_key")
    if not isinstance(recommendation_run_id, str) or recommendation_run_id == "":
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "VALIDATION_ERROR", "field": "recommendation_run_id"})
        return _err("VALIDATION_ERROR", "recommendation_run_id must be a non-empty string", field="recommendation_run_id")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int):
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "VALIDATION_ERROR", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size must be an integer", field="page_size")
    if page_size < 1 or page_size > 200:
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "VALIDATION_ERROR", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size out of range (1..200)", field="page_size")

    token_obj = _decode_token(page_token)
    if page_token is not None and token_obj is None:
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "VALIDATION_ERROR", "field": "page_token"})
        return _err("VALIDATION_ERROR", "page_token is invalid", field="page_token")

    # Authenticate api_key by id (or client-visible value). Store only has id/prefix/hash; tools pass id.
    keys = _load("api_keys.json")
    key_row = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break

    # Log request_received regardless of auth outcome (api_key_id can be null if invalid)
    _append_usage("request_received", api_key_id=key_row.get("id") if key_row else None, recommendation_run_id=recommendation_run_id,
                  units=0, http_status=None, latency_ms=None, metadata={"endpoint": "kakao_map_recommendation_items_list"})

    if not key_row:
        _append_usage("request_failed", api_key_id=None, recommendation_run_id=recommendation_run_id, units=0,
                      http_status=401, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        _append_usage("request_failed", api_key_id=key_row.get("id"), recommendation_run_id=recommendation_run_id, units=0,
                      http_status=401, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "UNAUTHORIZED", "key_status": key_row.get("status")})
        return _err("UNAUTHORIZED", "API key is not active", key_status=key_row.get("status"))

    runs = _load("recommendation_runs.json")
    run = None
    for r in runs:
        if isinstance(r, dict) and r.get("id") == recommendation_run_id:
            run = r
            break

    if not run or run.get("api_key_id") != key_row.get("id"):
        _append_usage("request_failed", api_key_id=key_row.get("id"), recommendation_run_id=recommendation_run_id, units=0,
                      http_status=404, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Recommendation run not found")

    # Cursor logic: order by (rank asc, id asc). Token contains last_rank, last_id, run_id, key_id.
    start_after = None
    if token_obj:
        if token_obj.get("recommendation_run_id") != recommendation_run_id or token_obj.get("api_key_id") != key_row.get("id"):
            _append_usage("request_failed", api_key_id=key_row.get("id"), recommendation_run_id=recommendation_run_id, units=0,
                          http_status=400, latency_ms=int((time.time() - t0) * 1000),
                          metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "VALIDATION_ERROR", "field": "page_token"})
            return _err("VALIDATION_ERROR", "page_token does not match request context", field="page_token")
        lr = token_obj.get("last_rank")
        lid = token_obj.get("last_id")
        if not isinstance(lr, int) or not isinstance(lid, str):
            _append_usage("request_failed", api_key_id=key_row.get("id"), recommendation_run_id=recommendation_run_id, units=0,
                          http_status=400, latency_ms=int((time.time() - t0) * 1000),
                          metadata={"endpoint": "kakao_map_recommendation_items_list", "error": "VALIDATION_ERROR", "field": "page_token"})
            return _err("VALIDATION_ERROR", "page_token is invalid", field="page_token")
        start_after = (lr, lid)

    items = _load("recommendation_items.json")
    places = _load("places.json")
    place_by_id = {p.get("id"): p for p in places if isinstance(p, dict) and p.get("id") is not None}

    run_items = [it for it in items if isinstance(it, dict) and it.get("recommendation_run_id") == recommendation_run_id]
    run_items.sort(key=lambda x: (x.get("rank") if isinstance(x.get("rank"), int) else 10**18, x.get("id") or ""))

    # Apply cursor
    if start_after is not None:
        lr, lid = start_after
        filtered = []
        for it in run_items:
            rk = it.get("rank")
            iid = it.get("id") or ""
            if isinstance(rk, int) and ((rk > lr) or (rk == lr and iid > lid)):
                filtered.append(it)
        run_items = filtered

    total = len([it for it in items if isinstance(it, dict) and it.get("recommendation_run_id") == recommendation_run_id])

    page = run_items[:page_size]
    data = []
    for it in page:
        pl = place_by_id.get(it.get("place_id"))
        data.append({
            "item": it,
            "place": pl
        })

    has_more = len(run_items) > page_size
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_token({
            "recommendation_run_id": recommendation_run_id,
            "api_key_id": key_row.get("id"),
            "last_rank": last.get("rank"),
            "last_id": last.get("id")
        })

    # update last_used_at for successful auth + call
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    _append_usage("request_succeeded", api_key_id=key_row.get("id"), recommendation_run_id=recommendation_run_id, units=0,
                  http_status=200, latency_ms=int((time.time() - t0) * 1000),
                  metadata={"endpoint": "kakao_map_recommendation_items_list", "returned": len(data)})

    return {
        "recommendation_run": run,
        "data": data,
        "page": {
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

def kakao_map_recommendation_run_cancel(api_key, recommendation_run_id, reason=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0446000" if __import__("os").path.isdir("./environment_mix/0446000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "kakao_map_recommendation_run_cancel"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return _now().isoformat()

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(n=26):
        return "".join(random.choice(_CROCK) for _ in range(n))
    def _gen_id(prefix):
        return f"{prefix}_{_ulid_like(26)}"

    def _append_usage(event_type, api_key_id=None, rec_id=None, units=1, http_status=None, upstream_status=None, latency_ms=None, metadata=None):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        ts = _now()
        if not isinstance(metadata, dict):
            metadata = {}
        valid_types = ("request_received", "quota_checked", "upstream_called", "request_succeeded", "request_failed")
        if event_type not in valid_types:
            # don't coerce silently into success types; record failed
            event_type = "request_failed"
            metadata = {**metadata, "note": "invalid_event_type"}
        if not isinstance(units, int) or units < 0:
            return False

        if latency_ms is not None and (not isinstance(latency_ms, int) or latency_ms < 0):
            return False
        if http_status is not None and (not isinstance(http_status, int) or http_status < 100 or http_status > 599):
            return False
        if upstream_status is not None and (not isinstance(upstream_status, int) or upstream_status < 100 or upstream_status > 599):
            return False

        row = {
            "id": _gen_id("kmap_use"),
            "api_key_id": api_key_id,
            "recommendation_run_id": rec_id,
            "event_type": event_type,
            "units": units,
            "http_status": http_status,
            "upstream_status": upstream_status,
            "latency_ms": latency_ms,
            "metadata": metadata,
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        }
        usage.append(row)
        _save("usage_events.json", usage)
        return True

    def _envelope(status_code, body, api_key_id=None, rec_id=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        if not isinstance(meta, dict):
            meta = {}
        # record a usage event for the operation itself (request_received then succeeded/failed)
        _append_usage("request_received", api_key_id=api_key_id, rec_id=rec_id, units=1, http_status=None, latency_ms=latency_ms, metadata={"endpoint": endpoint, **meta})
        if isinstance(body, dict) and "error" in body:
            _append_usage("request_failed", api_key_id=api_key_id, rec_id=rec_id, units=1, http_status=status_code, latency_ms=latency_ms, metadata={"endpoint": endpoint, **meta, "error_code": body["error"].get("code")})
        else:
            _append_usage("request_succeeded", api_key_id=api_key_id, rec_id=rec_id, units=1, http_status=status_code, latency_ms=latency_ms, metadata={"endpoint": endpoint, **meta})
        return body

    # ---------- validate inputs ----------
    if not isinstance(api_key, str) or not api_key:
        return _envelope(400, _err("VALIDATION_ERROR", "api_key must be a non-empty string"))
    if not re.match(r"^kmap_key_[0-9A-HJKMNP-TV-Z]{18,}$", api_key):
        return _envelope(400, _err("VALIDATION_ERROR", "api_key must match pattern ^kmap_key_[0-9A-HJKMNP-TV-Z]{18,}$"))
    if not isinstance(recommendation_run_id, str) or not recommendation_run_id:
        return _envelope(400, _err("VALIDATION_ERROR", "recommendation_run_id must be a non-empty string"))
    if reason is not None and not isinstance(reason, str):
        return _envelope(400, _err("VALIDATION_ERROR", "reason must be a string when provided"))

    # ---------- authenticate api_key (by id OR visible prefix, never by hash) ----------
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    key_row = None
    # match by exact id first; if not found, allow matching by prefix (client-visible)
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        for k in keys:
            if isinstance(k, dict) and k.get("key_prefix") and isinstance(k.get("key_prefix"), str) and api_key.startswith(k.get("key_prefix")):
                key_row = k
                break
    if key_row is None:
        # no credential in store matches what client sent
        return _envelope(401, _err("UNAUTHORIZED", "API key not recognized"), api_key_id=None, rec_id=recommendation_run_id)

    api_key_id = key_row.get("id")
    key_status = key_row.get("status")

    # For cancellation, a key must be usable for authorization. If key is revoked, refuse; if suspended, allow visibility check to proceed?
    # Realistic behavior: revoked keys are not authorized; suspended keys may be temporarily blocked.
    if key_status == "revoked":
        return _envelope(401, _err("UNAUTHORIZED", "API key is revoked; cancellation not authorized", status=key_status), api_key_id=api_key_id, rec_id=recommendation_run_id)
    if key_status == "suspended":
        return _envelope(401, _err("UNAUTHORIZED", "API key is suspended; cancellation not authorized while suspended", status=key_status), api_key_id=api_key_id, rec_id=recommendation_run_id)

    # ---------- locate run and enforce visibility ----------
    runs = _load("recommendation_runs.json")
    if not isinstance(runs, list):
        runs = []
    run = None
    run_idx = None
    for i, r in enumerate(runs):
        if isinstance(r, dict) and r.get("id") == recommendation_run_id:
            run = r
            run_idx = i
            break
    if run is None:
        return _envelope(404, _err("NOT_FOUND", "Recommendation run not found"), api_key_id=api_key_id, rec_id=recommendation_run_id)

    # Visibility rule per tool description: NOT_FOUND if run is not visible to provided api_key.
    # We scope by api_key_id when the run recorded one; internal/unauthenticated runs are not visible to arbitrary keys.
    run_key_id = run.get("api_key_id")
    if run_key_id is None:
        return _envelope(404, _err("NOT_FOUND", "Recommendation run not visible to this API key"), api_key_id=api_key_id, rec_id=recommendation_run_id)
    if run_key_id != api_key_id:
        return _envelope(404, _err("NOT_FOUND", "Recommendation run not visible to this API key"), api_key_id=api_key_id, rec_id=recommendation_run_id)

    # ---------- enforce lifecycle transition ----------
    status = run.get("status")
    allowed = {"queued": ["running", "cancelled", "failed"], "running": ["succeeded", "failed", "cancelled"], "succeeded": [], "failed": [], "cancelled": []}
    if status not in allowed:
        return _envelope(409, _err("CONFLICT", "Recommendation run is in an unknown state; cannot cancel", status=status), api_key_id=api_key_id, rec_id=recommendation_run_id)

    if status in ("succeeded", "failed", "cancelled"):
        return _envelope(409, _err("CONFLICT", "Recommendation run is already in a terminal state and cannot be cancelled", status=status), api_key_id=api_key_id, rec_id=recommendation_run_id)

    if "cancelled" not in allowed.get(status, []):
        return _envelope(409, _err("INVALID_TRANSITION", f"Cannot transition recommendation run from {status} to cancelled"), api_key_id=api_key_id, rec_id=recommendation_run_id)

    # ---------- persist mutation ----------
    now = _now()
    # update request_metadata with cancellation reason for auditability
    md = run.get("request_metadata")
    if not isinstance(md, dict):
        md = {}
    if reason:
        md = {**md, "cancel_reason": reason}
    md = {**md, "cancelled_by_api_key_id": api_key_id, "cancelled_at": _iso(now)}
    run["request_metadata"] = md

    run["status"] = "cancelled"
    # business rules: terminal states must not change; once cancelled we set finished_at
    # constraint: finished_at is null or started_at is not null. If we set finished_at, ensure started_at exists.
    if not run.get("started_at"):
        run["started_at"] = _iso(now)
    run["finished_at"] = _iso(now)
    run["updated_at"] = _iso(now)

    runs[run_idx] = run
    try:
        _save("recommendation_runs.json", runs)
    except Exception:
        return _envelope(500, _err("CONFLICT", "Failed to persist cancellation (database write failed)"), api_key_id=api_key_id, rec_id=recommendation_run_id)

    # update api_keys.last_used_at on successful auth+mutation
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == api_key_id:
            keys[i] = key_row
            break
    try:
        _save("api_keys.json", keys)
    except Exception:
        # don't fail the already-persisted cancellation; just return run
        pass

    return _envelope(200, {"data": run}, api_key_id=api_key_id, rec_id=recommendation_run_id)

def kakao_map_usage_events_list(api_key, recommendation_run_id=None, event_type=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0446000" if __import__("os").path.isdir("./environment_mix/0446000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _parse_dt(v, field):
        if v is None:
            return None, None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string", field=field)
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time", field=field)

    def _append_usage(event_type_, api_key_id=None, recommendation_run_id_=None, units=0, http_status=None, upstream_status=None, latency_ms=None, metadata=None):
        usage = _load("usage_events.json")
        ts = datetime.datetime.now(datetime.timezone.utc)
        rid = "kmap_use_" + ts.strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "recommendation_run_id": recommendation_run_id_,
            "event_type": event_type_,
            "units": int(units),
            "http_status": http_status,
            "upstream_status": upstream_status,
            "latency_ms": latency_ms,
            "metadata": metadata if isinstance(metadata, dict) else {},
            "created_at": ts.isoformat(),
            "updated_at": ts.isoformat(),
        }
        usage.append(row)
        _save("usage_events.json", usage)
        return row

    def _decode_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or tok == "":
            return None
        try:
            pad = "=" * (-len(tok) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_token(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(api_key, str):
        _append_usage("request_failed", api_key_id=None, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "api_key"})
        return _err("VALIDATION_ERROR", "api_key must be a string", field="api_key")
    if not api_key.startswith("kmap_key_"):
        _append_usage("request_failed", api_key_id=None, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "api_key"})
        return _err("VALIDATION_ERROR", "api_key format is invalid", field="api_key")
    if recommendation_run_id is not None and (not isinstance(recommendation_run_id, str) or recommendation_run_id == ""):
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "recommendation_run_id"})
        return _err("VALIDATION_ERROR", "recommendation_run_id must be a non-empty string", field="recommendation_run_id")
    if event_type is not None:
        allowed = {"request_received", "quota_checked", "upstream_called", "request_succeeded", "request_failed"}
        if not isinstance(event_type, str) or event_type not in allowed:
            _append_usage("request_failed", api_key_id=api_key, recommendation_run_id_=recommendation_run_id, units=0,
                          http_status=400, latency_ms=int((time.time() - t0) * 1000),
                          metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "event_type"})
            return _err("VALIDATION_ERROR", "event_type is invalid", field="event_type")

    ca, e1 = _parse_dt(created_after, "created_after")
    if e1:
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "created_after"})
        return e1
    cb, e2 = _parse_dt(created_before, "created_before")
    if e2:
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "created_before"})
        return e2
    if ca and cb and not (ca < cb):
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "created_before"})
        return _err("VALIDATION_ERROR", "created_before must be after created_after", field="created_before")

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int):
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size must be an integer", field="page_size")
    if page_size < 1 or page_size > 500:
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size out of range (1..500)", field="page_size")

    token_obj = _decode_token(page_token)
    if page_token is not None and token_obj is None:
        _append_usage("request_failed", api_key_id=api_key, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=400, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "page_token"})
        return _err("VALIDATION_ERROR", "page_token is invalid", field="page_token")

    # Authenticate api_key; spec says "AUTH_ERROR" but contract requires UNAUTHORIZED
    keys = _load("api_keys.json")
    key_row = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break

    _append_usage("request_received", api_key_id=key_row.get("id") if key_row else None, recommendation_run_id_=recommendation_run_id,
                  units=0, metadata={"endpoint": "kakao_map_usage_events_list"})

    if not key_row:
        _append_usage("request_failed", api_key_id=None, recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=401, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        _append_usage("request_failed", api_key_id=key_row.get("id"), recommendation_run_id_=recommendation_run_id, units=0,
                      http_status=401, latency_ms=int((time.time() - t0) * 1000),
                      metadata={"endpoint": "kakao_map_usage_events_list", "error": "UNAUTHORIZED", "key_status": key_row.get("status")})
        return _err("UNAUTHORIZED", "API key is not active", key_status=key_row.get("status"))

    # Cursor: by created_at desc, then id desc. Token carries last_created_at,last_id, key_id, and filter fingerprint.
    start_after = None
    if token_obj:
        if token_obj.get("api_key_id") != key_row.get("id"):
            _append_usage("request_failed", api_key_id=key_row.get("id"), recommendation_run_id_=recommendation_run_id, units=0,
                          http_status=400, latency_ms=int((time.time() - t0) * 1000),
                          metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "page_token"})
            return _err("VALIDATION_ERROR", "page_token does not match request context", field="page_token")
        expected_filters = {
            "recommendation_run_id": recommendation_run_id,
            "event_type": event_type,
            "created_after": created_after,
            "created_before": created_before,
        }
        if token_obj.get("filters") != expected_filters:
            _append_usage("request_failed", api_key_id=key_row.get("id"), recommendation_run_id_=recommendation_run_id, units=0,
                          http_status=400, latency_ms=int((time.time() - t0) * 1000),
                          metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "page_token"})
            return _err("VALIDATION_ERROR", "page_token does not match filters", field="page_token")
        lca = token_obj.get("last_created_at")
        lid = token_obj.get("last_id")
        if not isinstance(lca, str) or not isinstance(lid, str):
            _append_usage("request_failed", api_key_id=key_row.get("id"), recommendation_run_id_=recommendation_run_id, units=0,
                          http_status=400, latency_ms=int((time.time() - t0) * 1000),
                          metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "page_token"})
            return _err("VALIDATION_ERROR", "page_token is invalid", field="page_token")
        dt_lca, e = _parse_dt(lca, "page_token.last_created_at")
