                          metadata={"endpoint": "kakao_map_usage_events_list", "error": "VALIDATION_ERROR", "field": "page_token"})
            return _err("VALIDATION_ERROR", "page_token is invalid", field="page_token")
        start_after = (dt_lca, lid)

