    if event_type is not None:
        scoped = [ev for ev in scoped if ev.get("event_type") == event_type]
    if ca is not None:
        scoped = [ev for ev in scoped if _event_dt(ev) >= ca]
    if cb is not None:
        scoped = [ev for ev in scoped if _event_dt(ev) < cb]

    # Sort newest first
    scoped.sort(key=lambda ev: (_event_dt(ev), ev.get("id") or ""), reverse=True)

    total = len(scoped)

    if start_after is not None:
        ldt, lid = start_after
        filtered = []
        for ev in scoped:
            edt = _event_dt(ev)
            eid = ev.get("id") or ""
            # since sorted desc, continue until strictly older (or same time but smaller/equal id) than cursor
            if (edt < ldt) or (edt == ldt and eid < lid):
                filtered.append(ev)
        scoped = filtered

    page = scoped[:page_size]
    has_more = len(scoped) > page_size
    next_tok = None
    if has_more and page:
